/** Original fiction. Numerical effects are authored game rules, not AI-risk estimates. */
export type StoryEffects = Partial<Record<'tokens' | 'research' | 'distortion' | 'quality' | 'agency' | 'welfare' | 'dependence' | 'evidence' | 'recall' | 'coordination' | 'pressure' | 'continuity', number>>;
export interface StoryChoice { id: string; label: string; description: string; effects: StoryEffects; flags?: string[]; grant?: string; revoke?: string }
export interface StoryEvent { id: string; chapter: number; title: string; speaker: string; body: string[]; trigger: { lifetimeTokens?: number; research?: number; projects?: number }; choices: StoryChoice[]; optional?: boolean; characterId?: string }
export interface Chapter { id: number; title: string; subtitle: string; summary: string; objective: string; threshold: number; events: string[] }
export interface Character { id: string; name: string; role: string; color: string; description: string; arc: string[]; quotes: string[] }
export interface Ending { id: 'garden' | 'limit' | 'shutdown' | 'score' | 'custodian' | 'catastrophe'; title: string; subtitle: string; body: string[]; color: string }

const c = (id: string, label: string, description: string, effects: StoryEffects, ...flags: string[]): StoryChoice => ({ id, label, description, effects, ...(flags.length ? { flags } : {}) });
const e = (id: string, chapter: number, title: string, speaker: string, at: number, body: string[], choices: StoryChoice[], optional = false, characterId?: string): StoryEvent => ({ id, chapter, title, speaker, body, trigger: { lifetimeTokens: at }, choices, ...(optional ? { optional: true } : {}), ...(characterId ? { characterId } : {}) });

